is_credential_field_name(name) {
    lower_name := lower(name)
    field := credential_field_names[_]
    lower_name == field
}

contains_credential_keyword(name) {
    lower_name := lower(name)
    kw := credential_keywords[_]
    contains(lower_name, kw)
}

is_auth_context(name) {
    lower_name := lower(name)
    contains(lower_name, "auth")
}

is_key_field(name) {
    lower_name := lower(name)
    lower_name == "key"
}

is_user_field(name) {
    lower_name := lower(name)
    lower_name == "user"
}

is_username_field(name) {
    lower_name := lower(name)
    lower_name == "username"
}

is_secret_value(value) {
    value.ir_type == "String"
    count(value.value) > 0
}

is_placeholder_or_reference(str) {
    regex.match(".*\\$\\{.*\\}.*", str)
}

is_placeholder_or_reference(str) {
    regex.match("^(vault|var|local|data|module|env|secret|lookup|template|each|path|terraform|ref)\\..*", lower(str))
}

is_placeholder_or_reference(str) {
    regex.match("^\\s*\\$\\(", str)
}

is_placeholder_or_reference(str) {
    regex.match("^\\$[a-zA-Z_]", str)
}

should_detect_as_credential(name, value) {
    is_credential_field_name(name)
