    hash_node.ir_type == "Hash"

    hash_keys := [k.key.value | some k; k := hash_node.value[_]]

    some entry
    entry := hash_node.value[_]
    key_name := entry.key.value

    check_result := check_string_value_credential(entry.value, key_name, path)
    check_result != null

    result := check_result
